        // EHMC_burnin_struct       EHMC_burnin_as_cpp_struct  = convert_R_List_EHMC_burnin_struct(EHMC_burnin_as_Rcpp_List);

        //// replicate these structs for thread-safety as we will be modifying them for burnin
